package serve

import (
	"flag"
	"testing"

	"github.com/subaud-tools/tools-common/wiregen"
)

// The wire has a type, generated by a Go test (tools-common's wiregen) and
// not a node script, so a renamed field fails `just verify` on every machine,
// node or not: `pending.suggestions` became `pending.instructions` once, and
// two browser gates died reading the old field for weeks before anyone saw.

// updateWire rewrites web/wire.d.ts instead of asserting it. `just wire`.
var updateWire = flag.Bool("update", false, "rewrite web/wire.d.ts from the Go structs")

// wireRoots is THE CONTRACT: every view struct the browser reads off
// /_galley/pending, /_galley/revise and /_galley/versions. Adding a struct here
// is how a new endpoint's payload becomes a type the browser cannot silently
// disagree with.
//
// The order is the order they are emitted in, and it is the order a reader
// meets them: the instruction round first, then the poll every page runs, then
// the history.
//
// TWO OF THESE WERE OUTSIDE IT UNTIL 2026-08-23, AND THE GAP HAD THE SAME SHAPE
// BOTH TIMES. GET /_galley/revise answered a `map[string]any` written inline —
// thirteen keys the page polls every second, none of them nameable in a .d.ts,
// so a rename could not have failed here and could only have failed in a
// browser as `undefined`. versionsView was a real struct whose CHILDREN
// (roundView, diffView, changeView) were all under contract while the envelope
// naming them was not, so `doc` and `rounds` were the two field names in the
// history payload nothing held either side to. A contract with a hole in the
// envelope is a contract about the letters and not the address.
var wireRoots = []any{
	PendingView{},
	InstructionView{},
	ReviseStateView{},
	versionsView{},
	roundView{},
	diffView{},
	changeView{},
}

const wirePath = "../../web/wire.d.ts"

func TestTheWireTypeIsCommitted(t *testing.T) {
	opts := wiregen.Options{Header: wireHeader, Regenerate: "just wire"}
	if err := wiregen.CheckCommitted(wirePath, wireRoots, opts, *updateWire); err != nil {
		t.Fatal(err)
	}
}

const wireHeader = `// wire.d.ts — THE GO↔JS CONTRACT, GENERATED. DO NOT EDIT.
//
// Written by internal/serve/wire_test.go from the json tags of the five view
// structs that ARE the wire: PendingView and InstructionView
// (internal/serve/editmode.go), roundView, diffView and changeView
// (internal/serve/versions.go), plus every struct they reach — including
// across a package boundary, which is how suggest.BlockRef and review.Region
// get here. A named string type with a Values() method is an enum, declared
// as a union of its values: tools-common's msgstate.State is MessageState.
//
// Regenerate with ` + "`just wire`" + `. A drift between this file and the Go
// structs fails ` + "`just verify`" + `, which is Go-only and therefore runs on every
// machine, in CI and in the pre-push hook, whether or not node is installed.
// That is the whole point of it: the rename of ` + "`pending.suggestions`" + ` to
// ` + "`pending.instructions`" + ` broke two browser gates and went unnoticed for
// weeks, because the only things that could see it were scripts nobody ran.
//
// READING THE OPTIONALITY, because it is stated honestly rather than
// conveniently:
//
//   - ` + "`x?: T`" + ` — the Go field carries ` + "`omitempty`" + `, so the key is ABSENT from
//     the payload when it is the zero value. An absent slice is not an empty
//     one and is not null.
//   - ` + "`x: T[] | null`" + ` — no ` + "`omitempty`" + `, so a nil slice is serialized as JSON
//     ` + "`null`" + `. The type says so rather than promising an array: ` + "`|| []`" + ` at the
//     reader is load-bearing, and a declaration that hid this would make the
//     one line protecting against it look like superstition.
//   - a ` + "`time.Time`" + ` is a string. It is not a shape on the wire.
`
